<script module>
  import { LayoutContext } from "./dynamic-layout-types";

  export { internalRenderNode, renderChildren };
</script>
<script lang="ts">
  import {
    type DynamicLayoutComponents,
    type RenderChildNodeSnippet
  } from "./dynamic-layout-types";
  import DivNode from "./DivNode.svelte";
  import DebugTreeNode from "./DebugTreeNode.svelte";
  import type { Snippet } from "svelte";
  import type { DynamicLayoutNode } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";

  interface Props {
    node: DynamicLayoutNode;
    components: DynamicLayoutComponents;
    renderChildNode?: RenderChildNodeSnippet;
    layoutContext?: LayoutContext;
  }

  let { node = $bindable(), components, renderChildNode, layoutContext }: Props = $props();

  if (!components["div"]) {
    components["div"] = DivNode;
  }

  // set the same type, if users have their own div, it'll be used here as well
  if (!components["children"]) {
    components["children"] = components["div"];
  }

  if (!components["debug"]) {
    components["debug"] = DebugTreeNode;
  }

  let chosenRenderChildNodeSnippet = renderChildNode ?? internalRenderNode;

  if (!layoutContext) {
    layoutContext = new LayoutContext({
      node,
      root: node,
      depth: 0
    }, {
      components,
      renderChildren,
      renderChildNode: chosenRenderChildNodeSnippet,
      genericRenderChildren
    });
  }
</script>

<!-- helper for components that can have children without any additional boilerplate,
maybe refactored to use sub snippets internally -->

<!--
  this can be used by any node to list children including the wrap so that it fits perfect in the component
  bonus you can override this generic one to get async loading of nodes as well :)
 -->
{#snippet genericRenderChildren (_layoutContext: LayoutContext, nodes: DynamicLayoutNode[], wrapChild: Snippet<[LayoutContext, DynamicLayoutNode]>)}
  {#each nodes as childNode (childNode.id)}
    {@render wrapChild(_layoutContext, childNode)}
  {/each}
{/snippet}


{#snippet renderChildren (_layoutContext: LayoutContext)}
  {#snippet wrapChild (_layoutContext: LayoutContext, childNode: DynamicLayoutNode)}
    {@render _layoutContext.render.renderChildNode(_layoutContext.subNode(childNode))}
  {/snippet}

  {@render _layoutContext.render.genericRenderChildren(_layoutContext, _layoutContext.node.children ?? [], wrapChild)}
{/snippet}

{#snippet internalRenderNode (_layoutContext: LayoutContext)}
  {@const _node = _layoutContext.node}
  {@const components = _layoutContext.components}
  {@const elementProps = _node.layoutData?.elementProps ?? {}}

  {#if components}
    {#key _node.type + '_' + _layoutContext.depth + '_' + _node.id}
      <div {...elementProps}>
        {#if components[_node.type]}
          {@const Component = components[_node.type]}
          <Component layoutContext={_layoutContext} />
        {:else}
          {@const DivNode = components["div"]}
          <DivNode layoutContext={_layoutContext}>

          </DivNode>
        {/if}
      </div>
    {/key}
  {:else}
    No components provided!
  {/if}
{/snippet}

{@render chosenRenderChildNodeSnippet(layoutContext)}
