<script lang="ts">
  import { type ComponentProps, LayoutContext } from "./dynamic-layout-types";
  import Self from "./DebugTreeNode.svelte";
  import {
    type DynamicLayoutNode,
    getLabel
  } from "$lib/components/composites/dynamic-layout-app-types/dynamic-layout-types";

  let {
    layoutContext,
    // default true when using it only as type, not in render call
    overrideContext = true,
    hintUsingDebugNode = true
  }: ComponentProps & {
    overrideContext?: boolean;
    hintUsingDebugNode?: boolean;
  } = $props();

  let node = $derived(layoutContext.node);
  let label = $derived(getLabel(layoutContext.node));

  let newLayoutContext = overrideContext ? new LayoutContext(layoutContext.nodeInformations, {
    ...layoutContext.render,
    renderChildNode: layoutContext.render.renderChildNode
  }) : layoutContext;
</script>

<style lang="scss">
  @use 'sass:list';

  code {
    background: #8d8d8d;
    color: #c03f3f;
    font-weight: bold;
    padding: 0.1em 0.3em;
    border-radius: 0.25rem;
  }

  .unknown-mode {
    padding-left: 0.5rem
  }

  // only works with 3 colors, adding more only the last 3 before last are used... realy really weird css behavior, but after one hour its enough.

  $colors: (rgba(255, 0, 0, .2), rgba(0, 255, 0, .2), rgba(255, 255, 0, .2));

  @for $i from 1 through list.length($colors) {
    :global(.unknown-mode):nth-child(#{list.length($colors)}n+#{$i}) {
      background: list.nth($colors, $i);
    }
  }
</style>

{#snippet renderChildNode (layoutContext: LayoutContext)}
  <Self layoutContext={layoutContext} overrideContext={false} hintUsingDebugNode={false}>
  </Self>
{/snippet}

{#if hintUsingDebugNode}
  <strong>Note: Using "debug" node</strong> <br /><br />
{/if}

<ul class="list-disc list-inside">
  <li class="ml-1">
    {layoutContext.depth}: <code>{node.type}</code>
    {#if label}
      - Label: <code>{label}</code>
    {/if}

    {#snippet wrapChild (_layoutContext: LayoutContext, childNode: DynamicLayoutNode)}
      {@render renderChildNode(_layoutContext.subNode(childNode))}
    {/snippet}

    {@render layoutContext.render.genericRenderChildren(newLayoutContext, wrapChild)}
  </li>
</ul>

